import{decideWithMetadata}from"#ai/decision-adapter.js";import{recordUsage}from"#harness/usage-sink.js";import{extractGatewayCostUsd}from"#harness/model-call/usage.js";async function decide(e){let t=await decideWithMetadata(e);return await recordUsage({costUsd:extractGatewayCostUsd(t.providerMetadata),inputTokens:t.usage.inputTokens,outputTokens:t.usage.outputTokens},{kind:`decision`}),{answers:t.answers,usage:{inputTokens:t.usage.inputTokens,outputTokens:t.usage.outputTokens,totalTokens:t.usage.totalTokens}}}export{decide};